55	const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
56	  sword: 100,
57	  amulet: 60,
58	  staff: 80,
59	  potion: 40,
60	  rune: 25,
61	  moonstone: 25,
62	};
63	
64	const sumOf = <T>(values: readonly T[], amountOf: (value: T) => number): number =>
65	  values.reduce((sum, value) => sum + amountOf(value), 0);
66	
67	const isKnownItemType = (type: string): boolean =>
68	  type in BASE_PREMIUM_BY_ITEM_TYPE;
69	
70	const rejectUnknownItemTypes = (items: readonly Item[]): void => {
71	  const unknownItem = items.find((item) => !isKnownItemType(item.type));
72	
73	  if (unknownItem !== undefined) {
74	    throw new Error(`Unknown item type: ${unknownItem.type}`);
75	  }
76	};
77	
78	const itemBasePremiumOf = (item: Item): number =>
79	  BASE_PREMIUM_BY_ITEM_TYPE[item.type];
80	
81	const BLOCK_PREMIUM = 60;
82	const BLOCK_SIZE = 3;
83	
84	const itemsGroupedByType = (
85	  items: readonly Item[],
86	): readonly (readonly Item[])[] => [
87	  ...items
88	    .reduce(
89	      (groups, item) =>
90	        groups.set(item.type, [...(groups.get(item.type) ?? []), item]),
91	      new Map<string, readonly Item[]>(),
92	    )
93	    .values(),
94	];
95	
96	const groupBasePremiumOf = (group: readonly Item[]): number =>
97	  group.length === BLOCK_SIZE
98	    ? BLOCK_PREMIUM
99	    : sumOf(group, itemBasePremiumOf);
100	
101	const CURSED_SURCHARGE_RATE = 0.5;
102	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
103	const HIGH_ENCHANTMENT_THRESHOLD = 5;
104	
105	const isCursed = (item: Item): boolean => item.cursed === true;
106	
107	const isHighlyEnchanted = (item: Item): boolean =>
108	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
109	
110	interface Surcharge {
111	  readonly appliesTo: (item: Item) => boolean;
112	  readonly rate: number;
113	}
114	
115	const SURCHARGES: readonly Surcharge[] = [
116	  { appliesTo: isCursed, rate: CURSED_SURCHARGE_RATE },
117	  { appliesTo: isHighlyEnchanted, rate: HIGH_ENCHANTMENT_SURCHARGE_RATE },
118	];
119	
120	const surchargeRateOf = (item: Item): number =>
121	  sumOf(SURCHARGES, (surcharge) =>
122	    surcharge.appliesTo(item) ? surcharge.rate : 0,
123	  );
124	
125	const itemSurchargeOf = (item: Item): number =>
126	  itemBasePremiumOf(item) * surchargeRateOf(item);
127	
128	const policyBasePremiumOf = (items: readonly Item[]): number =>
129	  sumOf(itemsGroupedByType(items), groupBasePremiumOf);
130	
131	const policySurchargeOf = (items: readonly Item[]): number =>
132	  sumOf(items, itemSurchargeOf);
133	
134	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
135	
136	const firstInsuranceSurchargeOf = (basePremium: number): number =>
137	  basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
138	
139	const LOYALTY_DISCOUNT_RATE = 0.2;
140	const LOYALTY_YEARS_THRESHOLD = 2;
141	
142	const loyaltyDiscountOf = (basePremium: number, customer: Customer): number =>
143	  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD
144	    ? basePremium * LOYALTY_DISCOUNT_RATE
145	    : 0;
146	
147	const FOLLOW_UP_DISCOUNT_RATE = 0.15;
148	
149	const followUpDiscountOf = (
150	  basePremium: number,
151	  previousQuoteCount: number,
152	): number =>
153	  previousQuoteCount > 0 ? basePremium * FOLLOW_UP_DISCOUNT_RATE : 0;
154	
155	const exactPremiumBeforeFeeOf = (
156	  items: readonly Item[],
157	  customer: Customer,
158	  previousQuoteCount: number,
159	): number => {
160	  const basePremium = policyBasePremiumOf(items);
161	
162	  return (
163	    basePremium +
164	    policySurchargeOf(items) +
165	    firstInsuranceSurchargeOf(basePremium) -
166	    loyaltyDiscountOf(basePremium, customer) -
167	    followUpDiscountOf(basePremium, previousQuoteCount)
168	  );
169	};
170	
171	const PROCESSING_FEE = 5;
172	
173	const quotePremiumOf = (
174	  items: readonly Item[],
175	  customer: Customer,
176	  previousQuoteCount: number,
177	): number => {
178	  rejectUnknownItemTypes(items);
179	
180	  return Math.ceil(
181	    exactPremiumBeforeFeeOf(items, customer, previousQuoteCount) +
182	      PROCESSING_FEE,
183	  );
184	};
185	
186	const INSURANCE_VALUE_BY_ITEM_TYPE: Record<string, number> = {
187	  sword: 1000,
188	  amulet: 600,
189	  rune: 250,
190	};
191	
192	const DEDUCTIBLE = 100;
193	const CAP_FACTOR = 2;
194	
195	const itemInsuranceValueOf = (item: Item): number =>
196	  INSURANCE_VALUE_BY_ITEM_TYPE[item.type];
197	
198	const insuranceSumOf = (items: readonly Item[]): number =>
199	  sumOf(items, itemInsuranceValueOf);
200	
201	const MASTER_ENCHANTMENT_THRESHOLD = 8;
202	const MASTER_ENCHANTMENT_REIMBURSEMENT_RATE = 0.5;
203	const FULL_REIMBURSEMENT_RATE = 1;
204	
205	const isMasterEnchanted = (item: Item): boolean =>
206	  (item.enchantment ?? 0) >= MASTER_ENCHANTMENT_THRESHOLD;
207	
208	const reimbursementRateOf = (item: Item): number =>
209	  isMasterEnchanted(item)
210	    ? MASTER_ENCHANTMENT_REIMBURSEMENT_RATE
211	    : FULL_REIMBURSEMENT_RATE;
212	
213	const damagedItemOf = (damage: Damage, items: readonly Item[]): Item =>
214	  items.find((item) => item.type === damage.itemType) as Item;
215	
216	const damagePayoutOf = (damage: Damage, items: readonly Item[]): number =>
217	  damage.amount * reimbursementRateOf(damagedItemOf(damage, items)) -
218	  DEDUCTIBLE;
219	
220	const capOf = (policy: QuoteStep): number =>
221	  insuranceSumOf(policy.items) * CAP_FACTOR;
222	
223	const claimResultOf = (
224	  step: ClaimStep,
225	  policies: readonly QuoteStep[],
226	): ClaimResult => {
227	  const policy = policies[step.policy];
228	  const payout = sumOf(step.incident.damages, (damage) =>
229	    damagePayoutOf(damage, policy.items),
230	  );
231	
232	  return { payout, remainingCap: capOf(policy) - payout };
233	};
234	
235	const quoteResultOf = (
236	  step: QuoteStep,
237	  customer: Customer,
238	  previousQuoteSteps: readonly QuoteStep[],
239	): QuoteResult => ({
240	  premium: quotePremiumOf(step.items, customer, previousQuoteSteps.length),
241	});
242	
243	const isQuoteStep = (step: Step): step is QuoteStep => step.op === "quote";
244	
245	const quoteStepsOf = (steps: readonly Step[]): readonly QuoteStep[] =>
246	  steps.filter(isQuoteStep);
247	
248	const quoteStepsBefore = (
249	  steps: readonly Step[],
250	  stepIndex: number,
251	): readonly QuoteStep[] => quoteStepsOf(steps.slice(0, stepIndex));
252	
253	export const runScenario = (scenario: Scenario): ScenarioResult => ({
254	  results: scenario.steps.map((step, stepIndex): StepResult =>
255	    isQuoteStep(step)
256	      ? quoteResultOf(
257	          step,
258	          scenario.customer,
259	          quoteStepsBefore(scenario.steps, stepIndex),
260	        )
261	      : claimResultOf(step, quoteStepsOf(scenario.steps)),
262	  ),
263	});
